import requests, time
H={'Accept':'application/json'}
ids=['0000-0001-6102-7846','0000-0002-0209-2784','0000-0002-1053-2030','0000-0002-2605-6569','0000-0003-0396-0333']

def gj(u):
    for i in range(5):
        r=requests.get(u, headers=H, timeout=20)
        if r.status_code==429:
            time.sleep(1+0.5*i); continue
        r.raise_for_status(); return r.json()
    return None

filt={}
for oid in ids:
    w=gj(f'https://pub.orcid.org/v3.0/{oid}/works')
    c=0
    if not (w and 'group' in w):
        filt[oid]=0; continue
    for g in w['group']:
        for s in g.get('work-summary',[]):
            put=s.get('put-code')
            if put is None: continue
            d=gj(f'https://pub.orcid.org/v3.0/{oid}/work/{put}')
            if not d: continue
            pub=d.get('publication-date') or {}
            y=(pub.get('year') or {}).get('value')
            m=(pub.get('month') or {}).get('value')
            t=(d.get('type') or '').lower()
            if not (y and str(y).isdigit() and int(y)<2020):
                continue
            if not (m and str(m).isdigit()):
                continue  # require month for higher confidence
            if 'preprint' in t:
                continue
            c+=1
    filt[oid]=c

avg=sum(filt.values())/len(ids)
print(filt)
print('High-confidence average:', round(avg,2))
